BEGIN;
SET standard_conforming_strings = on;
CREATE TABLE daily_balances (account_id TEXT, statement_id TEXT, balance_date DATE, balance_category TEXT, daily_balance DECIMAL(10, 2), apr_applied DECIMAL(5, 3), daily_periodic_rate DECIMAL(8, 6), PRIMARY KEY (account_id, balance_date, balance_category));
CREATE TABLE payment_allocations (allocation_id TEXT PRIMARY KEY, account_id TEXT, transaction_id TEXT, statement_id TEXT, payment_date DATE, total_payment DECIMAL(10, 2), minimum_payment_portion DECIMAL(10, 2), excess_payment_amount DECIMAL(10, 2), purchase_allocation DECIMAL(10, 2), cash_advance_allocation DECIMAL(10, 2), balance_transfer_allocation DECIMAL(10, 2), promo_allocation DECIMAL(10, 2));
CREATE TABLE regz_acceptances (batch_id TEXT PRIMARY KEY, kind TEXT NOT NULL);
CREATE TABLE regz_accounts (account_id TEXT PRIMARY KEY, credit_card BOOLEAN NOT NULL, consumer_plan BOOLEAN NOT NULL, open_end BOOLEAN NOT NULL, home_secured BOOLEAN NOT NULL);
CREATE TABLE regz_balances (account_id TEXT, balance_id TEXT, snapshot_date DATE, amount_cents BIGINT NOT NULL, apr DECIMAL(12, 6) NOT NULL, protected_cents BIGINT NOT NULL, secured BOOLEAN NOT NULL, program_id TEXT, PRIMARY KEY (account_id, balance_id, snapshot_date));
CREATE TABLE regz_correction_completions (error_id TEXT PRIMARY KEY, checkpoint_date DATE NOT NULL);
CREATE TABLE regz_credits (credit_id TEXT PRIMARY KEY, error_id TEXT NOT NULL, item_id TEXT NOT NULL, amount_cents BIGINT NOT NULL, posted_date DATE NOT NULL);
CREATE TABLE regz_cycles (account_id TEXT, start_date DATE, end_date DATE NOT NULL, due_date DATE NOT NULL, PRIMARY KEY (account_id, start_date));
CREATE TABLE regz_dispatches (dispatch_id TEXT PRIMARY KEY, error_id TEXT NOT NULL, recipient TEXT NOT NULL, notice_type TEXT NOT NULL, sent_date DATE NOT NULL, content_evidence TEXT NOT NULL);
CREATE TABLE regz_error_items (error_id TEXT, item_id TEXT, required_cents BIGINT NOT NULL, PRIMARY KEY (error_id, item_id));
CREATE TABLE regz_error_obligations (error_id TEXT PRIMARY KEY, determination_date DATE NOT NULL, deadline DATE NOT NULL, recipient TEXT NOT NULL);
CREATE TABLE regz_payment_heads (payment_id TEXT PRIMARY KEY, batch_id TEXT NOT NULL);
CREATE TABLE regz_payments (payment_id TEXT PRIMARY KEY, account_id TEXT NOT NULL, credited_date DATE NOT NULL, cycle_end DATE NOT NULL, total_cents BIGINT NOT NULL, minimum_cents BIGINT NOT NULL);
CREATE TABLE regz_posted_allocations (batch_id TEXT, payment_id TEXT NOT NULL, balance_id TEXT, minimum_cents BIGINT NOT NULL, excess_cents BIGINT NOT NULL, effective_apr DECIMAL(12, 6) NOT NULL, window_start DATE, "method" TEXT NOT NULL, decision_date DATE NOT NULL, PRIMARY KEY (batch_id, balance_id));
CREATE TABLE regz_posted_classifications (batch_id TEXT, program_id TEXT, qualifies BOOLEAN NOT NULL, PRIMARY KEY (batch_id, program_id));
CREATE TABLE regz_practices (account_id TEXT, effective_date DATE, convention TEXT NOT NULL, offset_days INT NOT NULL, authorization_evidence TEXT, PRIMARY KEY (account_id, effective_date));
CREATE TABLE regz_program_classifications (batch_id TEXT, program_id TEXT, qualifies BOOLEAN NOT NULL, PRIMARY KEY (batch_id, program_id));
CREATE TABLE regz_programs (program_id TEXT PRIMARY KEY, account_id TEXT NOT NULL, start_date DATE NOT NULL, expiration_date DATE NOT NULL, interest_accrues BOOLEAN NOT NULL, waived_on_payoff BOOLEAN NOT NULL, grace_period BOOLEAN NOT NULL, temporary_zero BOOLEAN NOT NULL, retroactive_interest BOOLEAN NOT NULL, interim_payment_required BOOLEAN NOT NULL);
CREATE TABLE regz_proposal_lines (batch_id TEXT, balance_id TEXT, minimum_cents BIGINT NOT NULL, excess_cents BIGINT NOT NULL, effective_apr DECIMAL(12, 6) NOT NULL, window_start DATE, PRIMARY KEY (batch_id, balance_id));
CREATE TABLE regz_proposals (batch_id TEXT PRIMARY KEY, payment_id TEXT NOT NULL, snapshot_date DATE NOT NULL, decision_date DATE NOT NULL, "method" TEXT NOT NULL, request_id TEXT, replaces_batch_id TEXT);
CREATE TABLE regz_request_lines (request_id TEXT, balance_id TEXT, amount_cents BIGINT NOT NULL, PRIMARY KEY (request_id, balance_id));
CREATE TABLE regz_requests (request_id TEXT PRIMARY KEY, payment_id TEXT NOT NULL, submitted_date DATE, basis TEXT NOT NULL, channel TEXT NOT NULL, affirmative BOOLEAN NOT NULL, form_completed BOOLEAN NOT NULL, required_condition BOOLEAN NOT NULL, issuer_elected BOOLEAN NOT NULL, supersedes_id TEXT);
CREATE TABLE regz_snapshot_sets (account_id TEXT, snapshot_date DATE, PRIMARY KEY (account_id, snapshot_date));
CREATE TABLE statements (statement_id TEXT PRIMARY KEY, account_id TEXT, cycle_start DATE, cycle_end DATE, minimum_payment DECIMAL(10, 2));
CREATE TABLE transactions (transaction_id TEXT PRIMARY KEY, account_id TEXT, statement_id TEXT, transaction_date DATE, post_date DATE, transaction_type TEXT, balance_category TEXT, amount DECIMAL(10, 2), merchant_name TEXT, is_disputed BOOLEAN);
CREATE EXTENSION provsql CASCADE;
SELECT provsql.add_provenance('regz_proposals');
COMMIT;
